// Copies benchmarks/results/summary.json (generated by
// benchmarks/synapse_bench/summarize.py) into the frontend, because the
// frontend's Docker build only sees frontend/. A test fails if the copy and
// the source ever differ, so it can't silently go stale.
import { copyFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const source = resolve(here, "../../benchmarks/results/summary.json");
const target = resolve(here, "../src/benchmarks/summary.json");
copyFileSync(source, target);
console.log(`copied ${source} -> ${target}`);
